// The faces, self-hosted from their Fontsource packages (SIL Open Font License 1.1).
// next/font sizes a metric-matched fallback for each, so the swap shifts nothing.
import localFont from "next/font/local";

export const display = localFont({
  // Generated by scripts/fonts.mjs: Archivo cut to wght 300-650 and wdth 100-125.
  src: "./generated/archivo-display.woff2",
  variable: "--font-display",
  weight: "300 650",
  display: "swap",
  // Preloaded: the hero headline, the page's LCP element, is set in it.
  declarations: [{ prop: "font-stretch", value: "100% 125%" }],
});

export const narrow = localFont({
  src: "../../node_modules/@fontsource/archivo-narrow/files/archivo-narrow-latin-600-normal.woff2",
  variable: "--font-narrow",
  weight: "600",
  display: "swap",
  preload: false,
});

export const mono = localFont({
  src: [
    {
      path: "../../node_modules/@fontsource/dm-mono/files/dm-mono-latin-400-normal.woff2",
      weight: "400",
    },
    {
      path: "../../node_modules/@fontsource/dm-mono/files/dm-mono-latin-500-normal.woff2",
      weight: "500",
    },
  ],
  variable: "--font-mono",
  display: "swap",
  preload: false,
});
